        value === "else" ||
        value === "state" ||
        value === "endmodule" ||
        value === "end" ||
        value === "module" ||
        value === "initial" ||
        value === "begin" ||
        value === "bus" ||
        value === "mode" ||
        value === "flow" ||
        value === "reset" ||
        value === "wire" ||
        value === "input" ||
        value === "output" ||
        value === "inout"
