      height: route ? height : height - lastAfter,
      nRows: nRows,
      nCols: nCols,
      colW: colW,
      rowH: rowH,
      colX: colX,
      rowY: rowY,
      vSizes: vSizes,
      hSizes: hSizes,
      rowKind: rowKind
